def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_opp_defects = sum(1 for x in opp if x == 'D')
    if total_opp_defects * 2 > n:
        return 'D'

    exploits = 0
    retaliations = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i] == 'C':
            exploits += 1
            if opp[i + 1] == 'D':
                retaliations += 1

    if opp[-1] == 'D':
        if my[-1] == 'D':
            if n >= 2 and my[-2] == 'D':
                return 'C'
            return 'D'
        else:
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            recent_opp_coops = sum(1 for x in opp[-3:] if x == 'C')
            if recent_opp_coops >= 1:
                return 'C'
            return 'D'

    if my[-1] == 'D':
        return 'C'

    if exploits > 0 and retaliations == 0:
        if n % 3 == 0:
            return 'D'
        return 'C'
    else:
        if n >= 20 and total_opp_defects == 0 and n % 10 == 0:
            return 'D'
        return 'C'
